#!/bin/bash

# Define an empty string to hold the result
result=$'Consider the following source code:\n'

# Use git ls-files to get all tracked files that are not ignored
# This respects both local .gitignore and global gitignore
while IFS= read -r -d $'\0' file; do
    # Skip if file doesn't exist (could be deleted but staged)
    [ -f "$file" ] || continue
    
    # Additional exclusions on top of gitignore
    # Skip *.png files
    [[ "$file" == *.png ]] && continue
    # Skip *.lock files
    [[ "$file" == *.lock ]] && continue
    # Skip LICENSE files
    [[ "$(basename "$file")" == "LICENSE" ]] && continue
    
    # Use sed to remove the license text and append the modified file contents to the result string
    modified_content=$(cat "$file")

    result+="
${file}:
\`\`\`\`
$modified_content
\`\`\`\`
"
done < <(git ls-files -z --cached --others --exclude-standard | grep -zv '^$')

# Pipe the result into pbcopy
echo "$result" | pbcopy

